import React, { useState, useEffect } from 'react';
import api from '../services/api';
import Card from '../components/Card';
import Button from '../components/Button';
import Input from '../components/Input';
import Modal from '../components/Modal';

function Shifts() {
  const [shifts, setShifts] = useState([]);
  const [ministries, setMinistries] = useState([]);
  const [showForm, setShowForm] = useState(false);
  const [form, setForm] = useState({ name: '', ministry_id: '', day_of_week: '0', start_time: '09:00', end_time: '11:00' });

  useEffect(() => { loadData(); }, []);

  const loadData = async () => {
    const [s, m] = await Promise.all([api.get('/shifts.php'), api.get('/ministries.php')]);
    setShifts(s.data);
    setMinistries(m.data);
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    await api.post('/shifts.php', form);
    setShowForm(false);
    loadData();
  };

  const days = ['Domingo', 'Segunda', 'Terça', 'Quarta', 'Quinta', 'Sexta', 'Sábado'];

  return (
    <div style={{ maxWidth: 800, margin: '0 auto' }}>
      <div style={{ display: 'flex', justifyContent: 'space-between', marginBottom: 20 }}>
        <h1>Turnos</h1>
        <Button onClick={() => setShowForm(true)}>Novo Turno</Button>
      </div>
      {shifts.map(s => (
        <Card key={s.id} style={{ marginBottom: 10 }}>
          <strong>{s.name}</strong> - {days[s.day_of_week]} ({s.start_time} - {s.end_time})
        </Card>
      ))}
      <Modal isOpen={showForm} onClose={() => setShowForm(false)} title="Novo Turno">
        <form onSubmit={handleSubmit}>
          <Input label="Nome" value={form.name} onChange={e => setForm({...form, name: e.target.value})} />
          <select value={form.ministry_id} onChange={e => setForm({...form, ministry_id: e.target.value})} style={{ padding: 12, width: '100%', marginBottom: 16 }}>
            <option value="">Selecione Ministerio</option>
            {ministries.map(m => <option key={m.id} value={m.id}>{m.name}</option>)}
          </select>
          <Button type="submit">Salvar</Button>
        </form>
      </Modal>
    </div>
  );
}
export default Shifts;
